import unittest

from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object_Label import ManagedObjectLabel


class TestManagedObjectLabel(unittest.TestCase):
    def setUp(self):
        self.lnbts = ManagedObjectLabel("MRBTS-88/LNBTS-88")
        self.mrbts = ManagedObjectLabel("MRBTS-88")
        self.iprm = ManagedObjectLabel("MRBTS-88/LNBTS-88/FTM-1/IPNO-1/IPRM-1")
        self.lcell = ManagedObjectLabel("MRBTS-88/BTSSCL-1/LCELL-2", {"BTSSCL-1": "ABC", "LCELL-2": "123"})
        self.longer_label = ManagedObjectLabel("MRBTS-1/LNBTS-1/LNCEL-1/LNCEL_FDD-0/MPUCCH_FDD-0")
        self.longest_label = ManagedObjectLabel("MRBTS-8/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/TOP-1/TOPF-1")

    def test_init(self):
        self.lnbts = ManagedObjectLabel("MRBTS-88/LNBTS-88")

    def test_get_name(self):
        self.assertEqual(self.lnbts.get_name(), "LNBTS-88")

    def test_has_parent(self):
        self.assertTrue(self.lnbts.has_parent())
        self.assertFalse(self.mrbts.has_parent())

    def test_get_index(self):
        self.assertEqual(self.lnbts.get_index(), "88")

    def test_get_class(self):
        self.assertEqual(self.lnbts.get_class(), "LNBTS")

    def test_get_class_lnbts(self):
        self.assertEqual(self.lnbts.get_parent_path(), "MRBTS-88")

    def test_get_class_mrbts(self):
        self.assertEqual(self.mrbts.get_parent_path(), "")

    def test_get_class_iprm(self):
        self.assertEqual(self.iprm.get_parent_path(), "MRBTS-88/LNBTS-88/FTM-1/IPNO-1")

    def test_is_blacklisted(self):
        self.assertTrue(self.lnbts.is_blacklisted())
        self.assertFalse(self.iprm.is_blacklisted())

    def test_get_to_replace_dict(self):
        self.assertEqual(self.lnbts.get_to_replace_dict(None), {})
        self.assertEqual(self.lnbts.get_to_replace_dict({"ABC": 1}), {"ABC": 1})

    def test_get_emss_name_lnbts(self):
        self.assertEqual(self.lnbts.get_yaml_name(), "LNBTS-88")

    def test_get_emss_name_lnbts_with_replaced_id(self):
        self.lnbts._to_replace = {"LNBTS-88": "ENB_ID"}
        self.assertEqual(self.lnbts.get_yaml_name(), "LNBTS-${ENB_ID}")

    def test_get_emss_name_iprm(self):
        self.iprm._to_replace = {"LNBTS-88": "ENB_ID"}
        self.assertEqual(self.iprm.get_yaml_name(), "IPRM-1-1")

    def test_get_emss_name_lcell(self):
        self.assertEqual(self.lcell.get_yaml_name(), "LCELL-${ABC}-${123}")

    def test_get_yaml_index(self):
        self.assertEqual(self.mrbts.get_yaml_index(), "88")
        self.assertEqual(self.iprm.get_yaml_index(), "1-1")
        self.lnbts._to_replace = {"LNBTS-88": "ENB_ID"}
        self.assertEqual(self.lnbts.get_yaml_index(), "${ENB_ID}")

    def test_get_emss_index(self):
        self.assertEqual(self.mrbts.get_emss_index(), "88")
        self.assertEqual(self.iprm.get_emss_index(), "1-1")
        self.lnbts._to_replace = {"LNBTS-88": "ENB_ID"}
        self.assertEqual(self.lnbts.get_emss_index(), "88")

    def test_get_fake_index_same(self):
        self.assertEqual(self.mrbts.get_fake_index(), "88")

    def test_get_fake_index_replaced(self):
        self.lnbts._to_replace = {"LNBTS-88": "ENB_ID"}
        self.assertEqual(self.lnbts.get_fake_index(), "${ENB_ID}")

    def test_get_emss_name_longer(self):
        self.assertEqual(self.longer_label.get_yaml_name(), "MPUCCH_FDD-1-0-0")

    def test_get_emss_name_longest(self):
        self.assertEqual(self.longest_label.get_yaml_name(), "TOPF-1-1-1-1-1-1")


if __name__ == "__main__":
    unittest.main()
